// Generated from src/registry/sources/control-ui/recipes/item.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const itemKnobs = [
  "--cui-item-radius",
  "--cui-item-hover-background",
  "--cui-item-hover-border-color",
  "--cui-item-border-width",
  "--cui-item-active-scale",
] as const;
export type ItemKnobStyle = Partial<Record<(typeof itemKnobs)[number], string>>;

@layer components {
  :where([data-control-family="item"][data-slot="root"]) {
    --cui-item-radius: var(--radius-lg);
    --cui-item-hover-background: transparent;
    --cui-item-hover-border-color: var(--_item-border-color);
    --cui-item-border-width: 0px;
    --cui-item-active-scale: 1;
    --_item-background: transparent;
    --_item-border-color: transparent;
    outline: var(--cui-item-border-width) solid var(--_item-border-color);
    outline-offset: calc(-1 * var(--cui-item-border-width));
    border-radius: var(--cui-item-radius);
    background: var(--_item-background);
    box-shadow: none;
    color: var(--foreground);
    transition-property: background-color, box-shadow, color, outline-color, scale;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
    gap: calc(var(--spacing) * 3);
    padding: calc(var(--spacing) * 3);
  }

  :where([data-control-family="item"][data-slot="content"]) {
    gap: calc(var(--spacing) * 0.5);
  }

  :where([data-control-family="item"][data-slot="actions"]) {
    gap: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="item"][data-slot="header"]),
  :where([data-control-family="item"][data-slot="footer"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="item"][data-slot="root"][data-variant="outline"]) {
    --_item-border-color: var(--border);
    --cui-item-border-width: 1px;
  }

  :where([data-control-family="item"][data-slot="root"][data-variant="muted"]) {
    --_item-background: oklch(from var(--muted) l c h / 0.5);
  }

  :where([data-control-family="item"][data-slot="root"]:is(a, button, [href], [role="button"]):hover) {
    outline-color: var(--cui-item-hover-border-color);
    background: var(--cui-item-hover-background);
    box-shadow: none;
  }

  :where([data-control-family="item"][data-slot="root"]:is(a, button, [href], [role="button"]):active) {
    scale: var(--cui-item-active-scale);
  }

  :where([data-control-family="item"][data-slot="footer"]) {
    font-size: var(--text-caption);
    color: var(--muted-foreground);
  }

  :where([data-control-family="item"][data-slot="description"]) {
    font-size: var(--text-sm);
    line-height: var(--leading-relaxed);
    color: var(--muted-foreground);
  }

  :where([data-control-family="item"][data-slot="title"]) {
    gap: calc(var(--spacing) * 2);
    font-size: var(--text-sm);
    font-weight: var(--font-weight-medium);
    line-height: 1;
    color: var(--foreground);
  }

  :where([data-control-family="item"][data-slot="media"]) {
    color: var(--muted-foreground);
  }
}

@property --cui-item-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-item-hover-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --cui-item-hover-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-item-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-item-active-scale {
  syntax: "<number>";
  inherits: true;
  initial-value: 1;
}

"use client";

import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, CSSProperties } from "react";
import type { RenderProp } from "@/components/control-ui/control-props";
import type { ItemKnobStyle } from "@/components/control-ui/knob-contracts/item-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { Separator } from "@/components/control-ui/ui/separator";

export const itemVariants = ["default", "outline", "muted"] as const;

export type ItemVariant = (typeof itemVariants)[number];

export type ItemProps = Omit<
  ComponentProps<"div"> & {
    variant?: ItemVariant;
    render?: RenderProp<ComponentProps<"div">>;
  },
  "style"
> & { style?: CSSProperties & ItemKnobStyle };

export type ItemDescriptionProps = Omit<ComponentProps<"p">, "style"> & { style?: CSSProperties & ItemKnobStyle };

export type ItemFooterProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & ItemKnobStyle };

export type ItemMediaProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & ItemKnobStyle };

export type ItemTitleProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & ItemKnobStyle };

export type ItemGroupProps = ComponentProps<"div"> & { style?: CSSProperties & ItemKnobStyle };

export type ItemSeparatorProps = ComponentProps<"div">;

export function ItemGroup({ className, ...props }: ItemGroupProps) {
  return (
    // biome-ignore lint/a11y/useSemanticElements: Item may render as a link or button, so a ul would require invalid wrappers.
    <div
      role="list"
      data-control-ui="item"
      data-control-family="item"
      data-slot="group"
      className={cn("group/item-group flex flex-col", className)}
      {...props}
    />
  );
}

export function ItemSeparator({ className, ...props }: ItemSeparatorProps) {
  return <Separator data-control-ui="item" data-slot="separator" orientation="horizontal" className={cn("my-0", className)} {...props} />;
}

export function Item({ variant = "default", render, className, children, ...props }: ItemProps) {
  return useRender({
    defaultTagName: "div",
    render,
    props: {
      ...props,
      "data-control-ui": "item",
      "data-control-family": "item",
      "data-slot": "root",
      "data-variant": variant,
      className: cn("flex items-center [&[href]]:cursor-pointer", className),
      children,
    },
  });
}

export function ItemMedia({ className, ...props }: ItemMediaProps) {
  return (
    <div
      data-control-ui="item"
      data-control-family="item"
      data-slot="media"
      className={cn("flex shrink-0 items-center justify-center self-start [&>svg]:size-5 [&>svg]:shrink-0", className)}
      {...props}
    />
  );
}

export function ItemContent({ className, ...props }: ComponentProps<"div"> & { style?: CSSProperties & ItemKnobStyle }) {
  return (
    <div
      data-control-ui="item"
      data-control-family="item"
      data-slot="content"
      className={cn("flex min-w-0 flex-1 flex-col", className)}
      {...props}
    />
  );
}

export function ItemTitle({ className, ...props }: ItemTitleProps) {
  return (
    <div
      data-control-ui="item"
      data-control-family="item"
      data-slot="title"
      className={cn("flex w-fit items-center", className)}
      {...props}
    />
  );
}

export function ItemDescription({ className, ...props }: ItemDescriptionProps) {
  return (
    <p data-control-ui="item" data-control-family="item" data-slot="description" className={cn("line-clamp-2", className)} {...props} />
  );
}

// never shrinks, so long content column cannot squeeze actions
export function ItemActions({ className, ...props }: ComponentProps<"div"> & { style?: CSSProperties & ItemKnobStyle }) {
  return (
    <div
      data-control-ui="item"
      data-control-family="item"
      data-slot="actions"
      className={cn("flex shrink-0 items-center", className)}
      {...props}
    />
  );
}

export function ItemHeader({ className, ...props }: ComponentProps<"div"> & { style?: CSSProperties & ItemKnobStyle }) {
  return (
    <div
      data-control-ui="item"
      data-control-family="item"
      data-slot="header"
      className={cn("flex basis-full items-center justify-between", className)}
      {...props}
    />
  );
}

export function ItemFooter({ className, ...props }: ItemFooterProps) {
  return (
    <div
      data-control-ui="item"
      data-control-family="item"
      data-slot="footer"
      className={cn("flex basis-full items-center justify-between", className)}
      {...props}
    />
  );
}
